function LinkedDevicesWeb(){const[devices,setDevices]=useState<any[]>([]),[loading,setLoading]=useState(true),[error,setError]=useState("");const load=async()=>{setLoading(true);try{const r=await api<any>("/messages/crypto/devices");setDevices(r.devices||[])}catch(e){setError(e instanceof Error?e.message:"Unable to load linked devices.")}finally{setLoading(false)}};useEffect(()=>{void load()},[]);return <><Header route={byKey("LinkedDevices")!} title="Linked devices" subtitle="Authenticated encryption devices returned by the ReDom messaging service."/><section className="parity-card">{error?<div className="parity-error">{error}</div>:null}{loading?<div className="parity-loading">Loading encrypted devices…</div>:devices.length?devices.map(d=><article className="parity-device" key={d.device_id}><div><b>{d.device_label||d.platform+" device"}</b><p>{d.platform||"Unknown platform"}{d.primary_device?" · Primary":""}</p><small>Added {new Date(d.created_at).toLocaleString()} · Last active {new Date(d.updated_at).toLocaleString()}</small></div><span>{d.primary_device?"Primary":"Active"}</span></article>):<Empty title="No active devices" text="The backend returned no active encryption devices for this account."/>}<Button kind="secondary" onClick={()=>void load()}>Refresh</Button></section></>}

