function AuthParityScreen({route}:{route:WebRoute}){const [values,setValues]=useState<Record<string,string>>({});const fields=routeMeta[route.key]?.fields||[];const steps=["RegistrationWelcome","RegistrationIdentity","RegistrationBirthday","RegistrationGender","RegistrationPhone","RegistrationEmail","RegistrationPassword","RegistrationReview","RegistrationVerification","CustomizingExperience"];const idx=steps.indexOf(route.key);const next=idx>=0&&steps[idx+1]?steps[idx+1]:"Login";return <div className="auth-parity"><div className="auth-card"><Img src={ReDomLogo} className="auth-logo"/><div className="parity-eyebrow">{route.category}</div><h1>{route.title}</h1><p>{route.description}</p>{fields.map(x=><Field key={x} label={x} value={values[x]||""} onChange={v=>setValues(s=>({...s,[x]:v}))} type={x.toLowerCase().includes("password")?"password":"text"} placeholder={x}/>)}<Button onClick={()=>go(nextFor(route.key==="Login"?"DeviceVerification":route.key==="FindAccount"?"DeviceVerification":next))}>{route.key==="CustomizingExperience"?"Continue to ReDom":"Continue"}</Button><button className="auth-back" onClick={()=>go("/app/login")}>Back</button></div></div>;}
function RouteData({route,user}:{route:WebRoute;user:User}){const meta=routeMeta[route.key]||{icon:ReDomMark};const [values,setValues]=useState<Record<string,string>>({});const [items,setItems]=useState<any[]>([]);const [loading,setLoading]=useState(false);const [error,setError]=useState("");const [done,setDone]=useState("");const [enabled,setEnabled]=useState(false);const refresh=async()=>{if(!meta.endpoint)return;setLoading(true);setError("");try{const r=await api<any>(meta.endpoint);const raw=r?.items??r?.data??r?.results??r?.notifications??r?.groups??r?.transactions??r?.paymentMethods??r?.products??r?.cases??[];setItems(Array.isArray(raw)?raw:[raw]);}catch(e){setError(e instanceof Error?e.message:"Unable to load ReDom data.");}finally{setLoading(false)}};useEffect(()=>{void refresh()},[route.key]);const submit=async()=>{setLoading(true);setError("");try{if(route.key==="DarkMode"){document.documentElement.dataset.theme=enabled?"dark":"light";localStorage.setItem("redom-theme",enabled?"dark":"light");setDone("Appearance updated.");}else if(route.key==="Language"){localStorage.setItem("redom-language",values.Language||"English");setDone("Language preference saved.");}else if(meta.endpoint){await api(meta.endpoint,{method:"POST",body:JSON.stringify(values)});setDone("Changes saved.");await refresh();}else setDone("Request submitted.");}catch(e){setError(e instanceof Error?e.message:"The action could not be completed.");}finally{setLoading(false)}};const fields=meta.fields||[];const choice=route.key==="AddPaymentMethod"||route.key==="OrdersPayments";return <div className="route-parity"><Header route={route} title={route.title} subtitle={route.description}/><section className="route-hero-card"><div className="route-icon"><Img src={meta.icon}/></div><div><h2>{route.title}</h2><p>{route.description}</p></div></section>{choice&&<div className="choice-grid"><button onClick={()=>go(nextFor("AddCard"))}><Img src={VisaSvg}/><b>Credit or debit card</b><small>Secure card setup</small></button><button disabled><Img src={PaypalSvg}/><b>PayPal</b><small>Coming Soon</small></button><button disabled><Img src={BankPaymentSvg}/><b>Bank payment method</b><small>Under Development</small></button></div>}{route.key==="DarkMode"&&<div className="route-control-row"><div><b>Dark mode</b><small>Change the appearance of ReDom Web.</small></div><button className={"toggle "+(enabled?"on":"")} onClick={()=>setEnabled(v=>!v)}><i/></button></div>}{route.key==="Language"&&<div className="choice-list">{["English","Español","Français","Deutsch"].map(x=><button key={x} className="choice-row" onClick={()=>setValues({Language:x})}>{x}<span>›</span></button>)}</div>}{fields.length>0&&<section className="route-form">{fields.map(x=><Field key={x} label={x} value={values[x]||""} onChange={v=>setValues(s=>({...s,[x]:v}))} type={x.toLowerCase().includes("pin")||x.toLowerCase().includes("password")?"password":"text"} placeholder={x}/>) }<Button onClick={()=>void submit()} disabled={loading}>{loading?"Processing…":"Save changes"}</Button>{done&&<div className="parity-success">{done}</div>}{error&&<div className="parity-error">{error}</div>}</section>}{route.key==="Verification"&&<div className="verification-card"><Img src={SecuritySvg}/><h3>Account verification</h3><p>Verification status is read from the authenticated ReDom account.</p><Button onClick={()=>go(nextFor("Support"))}>Get help</Button></div>}{route.key==="ReDomAI"&&<div className="ai-parity"><div className="ai-message">ReDom AI</div><div className="ai-compose"><input value={values.Message||""} onChange={e=>setValues({...values,Message:e.target.value})} placeholder="Message ReDom AI"/><Button onClick={()=>void submit()}>Send</Button></div></div>}{meta.endpoint&&<section className="route-data-card"><div className="parity-section-title"><h2>Current information</h2><Button kind="secondary" onClick={()=>void refresh()} disabled={loading}>Refresh</Button></div>{error&&<div className="parity-error">{error}</div>}{loading?<div className="parity-loading">Loading…</div>:items.length?items.map((x,i)=><button className="route-data-row" key={x.id||x.userId||x.transactionId||i} onClick={()=>x.id&&go(route.key==="SupportInbox"?"/app/supportMessage":route.path)}><Avatar user={x.author||x.user||x} size={44}/><span><b>{x.name||x.title||x.subject||x.displayName||[x.firstName,x.lastName].filter(Boolean).join(" ")||route.title}</b><small>{x.status||x.description||x.body||x.message||x.content||x.email||"Open to view details."}</small></span><strong>{x.amount!=null?String(x.amount)+" "+(x.currency||""):"›"}</strong></button>):<div className="route-empty"><Img src={ReDomMark}/><h3>No data available</h3><p>There is currently no server data for this account on this screen.</p></div>}</section>}{!meta.endpoint&&!fields.length&&!choice&&!["DarkMode","Language","Verification","ReDomAI"].includes(route.key)&&<section className="route-content-card"><h2>{route.title}</h2><p>{route.description}</p><div className="route-action-grid"><Button kind="secondary" onClick={()=>go("/app/homeFeed")}>Back to Home Feed</Button><Button onClick={()=>setDone("Action completed.")}>Continue</Button></div>{done&&<div className="parity-success">{done}</div>}</section>}</div>;}

export function WebParityRouter({user,onLogout}:{user:User;onLogout:()=>void}){const[,setTick]=useState(0);useEffect(()=>{const f=()=>setTick(v=>v+1);window.addEventListener("popstate",f);return()=>window.removeEventListener("popstate",f)},[]);const sharedMatch=window.location.pathname.match(/^\/@([^/]+)$/);const sharedToken=new URLSearchParams(window.location.search).get("_t")||"";if(sharedMatch&&sharedToken)return <SharedProfileWeb username={decodeURIComponent(sharedMatch[1])} token={sharedToken}/>;const key=keyFromPath();const route=byKey(key)||WEB_SCREEN_REGISTRY[0];if(["Login","FindAccount","DeviceVerification","LoginTwoFactor"].includes(key)||route.category==="Registration")return <AuthParityScreen route={route}/>;let content:any;if(key==="HomeFeed")content=<HomeFeed user={user}/>;else if(key==="ReDomAI")content=<><div style={{maxWidth:920,margin:"0 auto 16px"}}><button className="parity-btn parity-primary" onClick={()=>go("/app/reDomVideoStudio")}>Open ReDom Video Studio</button></div><ReDomCreativeStudio/></>;else if(key==="ReDomVideoStudio")content=<ReDomVideoStudio/>;else if(key==="Profile")content=<Profile user={user}/>;else if(key==="Search")content=<Search/>;else if(key==="Notifications")content=<Notifications/>;else if(key==="Messages")content=<Messages/>;else if(key==="Groups")content=<GroupsWeb/>;else if(key==="Settings")content=<SettingsScreenWeb/>;else if(key==="EditProfile")content=<ProfileEditWeb/>;else content=<RouteData route={route} user={user}/>;return <Shell user={user} onLogout={onLogout}>{content}</Shell>;}
export function webParityRouteAudit(){const mobile=WEB_SCREEN_REGISTRY;const paths=new Set(mobile.map(x=>x.path));return {mobileCount:mobile.length,webCount:paths.size,duplicateMobileKeys:mobile.length-new Set(mobile.map(x=>x.key)).size,duplicatePaths:mobile.length-paths.size,missing:mobile.filter(x=>!paths.has(x.path)).map(x=>x.key)};}
